int edgeCount(std::vector<int> const& A, size_t N) {

        // Initialize the HPX execution environment
        hpx::init(nullptr, argc, argv);

        // Create a vector of indices
        std::vector<size_t> indices(N);
        std::iota(indices.begin(), indices.end(), 0);

        // Create a vector of edges
        std::vector<int> edges;

        // Parallelize the loop over the indices
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0,
            N,
            [&](size_t i) {
                for (size_t j = 0; j < N; ++j) {
                    if (A[i * N + j] == 1) {
                        edges.push_back(i);
                        edges.push_back(j);
                    }
                }
            }
        );

        // Shutdown the HPX execution environment
        hpx::finalize();

        // Return the size of the edges vector
        return edges.size() / 2;
}

