int largestComponent(std::vector<int> const& A, size_t N) {

        // Create a vector to store the visited nodes
        std::vector<bool> visited(N, false);

        // Initialize the maximum component size to 0
        int maxComponentSize = 0;

        // Iterate over each node in the graph
        for (size_t i = 0; i < N; ++i) {
            if (!visited[i]) {
                int componentSize = 0;
                std::vector<int> stack = {i};
                while (!stack.empty()) {
                    int node = stack.back();
                    stack.pop_back();
                    if (!visited[node]) {
                        visited[node] = true;
                        ++componentSize;
                        for (size_t j = 0; j < N; ++j) {
                            if (A[node * N + j] &&!visited[j]) {
