        // Iterate over each node
        for (size_t i = 0; i < N; ++i) {
            // If the node has not been visited
            if (!visited[i]) {
                // Create a queue for BFS
                std::queue<size_t> q;
                // Add the node to the queue and mark it as visited
                q.push(i);
                visited[i] = true;
