int largestComponent(std::vector<int> const& A, size_t N) {

        // Create a graph from the adjacency matrix
        hpx::lcos::promise<std::vector<std::vector<int>>> promise;
        hpx::apply([&](hpx::lcos::local::promise<std::vector<std::vector<int>>>&& p) {
            std::vector<std::vector<int>> graph(N, std::vector<int>(N));
            for (size_t i = 0; i < N; ++i) {
                for (size_t j = i; j < N; ++j) {
                    if (A[i * N + j] == 1) {
                        graph[i][j] = 1;
                        graph[j][i] = 1;
                    }
                }
            }
            p.set_value(std::move(graph));
        }, std::move(promise));

        // Wait for the graph to be ready
        auto graph = promise.get_future().get();

        // Use a depth-first search to find the size of the largest component
        std::vector<bool> visited(N, false);
        int maxComponentSize = 0;
        for (size_t i = 0; i < N; ++i) {
            if (!visited[i]) {
                int componentSize = 0;
                hpx::apply([&](size_t i, std::vector<bool>& visited, int& componentSize) {
                    std::stack<size_t> stack;
                    stack.push(i);
                    while (!stack.empty()) {
                        size_t node = stack.top();
                        stack.pop();
                        if (!visited[node]) {
                            visited[node] = true;
                            ++componentSize;
                            for (size_t j = 0; j < N; ++j) {
                                if (graph[node][j] == 1 &&!visited[j]) {
                                    stack.push(j);
                                }
                            }
                        }
                    }
                }, i, std::ref(visited), std::ref(componentSize));
                maxComponentSize = std::max(maxComponentSize, componentSize);
            }
        }

        return maxComponentSize;
}

