        int maxSize = 0;

        // Iterate over each node
        for (size_t i = 0; i < N; ++i) {
            // If the node has not been visited
            if (!visited[i]) {
                // Create a queue for BFS
                std::queue<int> q;
                q.push(i);
                visited[i] = true;

                // Initialize the size of the current component
                int componentSize = 0;

                // Perform BFS
                while (!q.empty()) {
                    int node = q.front();
                    q.pop();
                    ++componentSize;

