        // Find the size of the largest component
        int max_size = 0;
        for (size_t i = 0; i < N; ++i) {
            if (!visited[i]) {
                int size = dfs(dfs, i);
                if (size > max_size) {
                    max_size = size;
                }
            }
        }

        return max_size;
}

