int largestComponent(std::vector<int> const& A, size_t N) {

        // Create a vector to store the visited vertices
        std::vector<bool> visited(N, false);

        // Define a lambda function to perform depth-first search
        auto dfs = [&](auto&& self, int v) -> int {
            visited[v] = true;
            int count = 1;
            for (int i = 0; i < N; ++i) {
                if (A[v * N + i] &&!visited[i]) {
                    count += self(self, i);
                }
            }
            return count;
