        // Find the size of the largest component
        int max_component_size = 0;
        for (int i = 0; i < N; ++i) {
            if (!visited[i]) {
                max_component_size = std::max(max_component_size, dfs(dfs, i));
            }
        }

        return max_component_size;
}

