        std::vector<bool> visited(N, false);

        // Create a queue for BFS
        std::queue<int> q;

        // Initialize the largest component size
        int largestComponentSize = 0;

        // Iterate over each node
        for (int i = 0; i < N; ++i) {
            if (!visited[i]) {
                int componentSize = 0;
                q.push(i);
                visited[i] = true;

                // Perform BFS
                while (!q.empty()) {
                    int node = q.front();
                    q.pop();
                    componentSize++;

                    // Iterate over each neighbor of the node
                    for (int j = 0; j < N; ++j) {
                        if (A[node * N + j] == 1 &&!visited[j]) {
                            q.push(j);
                            visited[j] = true;
                        }
                    }
                }

                // Update the largest component size
                largestComponentSize = std::max(largestComponentSize, componentSize);
            }
        }

        return largestComponentSize;
}

