        hpx::lcos::promise<int> largest_component_size;

        hpx::apply([&largest_component_size, A, N]() {
            std::vector<bool> visited(N, false);
            int max_component_size = 0;

            for (size_t i = 0; i < N; ++i) {
                if (!visited[i]) {
                    int component_size = 0;
                    std::stack<size_t> stack;
                    stack.push(i);

                    while (!stack.empty()) {
