int largestComponent(std::vector<int> const& A, size_t N) {

        // Create a vector to store the visited nodes
        std::vector<bool> visited(N, false);

        // Define a lambda function to perform depth-first search
        auto dfs = [&](auto&& self, int node) -> int {
            if (visited[node]) return 0;
            visited[node] = true;
            int count = 1;
            for (int i = 0; i < N; ++i) {
                if (A[node * N + i] &&!visited[i]) {
                    count += self(self, i);
                }
            }
            return count;
        };

        // Initialize the maximum component size
        int maxComponentSize = 0;

        // Iterate over all nodes in the graph
        for (int i = 0; i < N; ++i) {
            if (!visited[i]) {
                // Perform depth-first search on the unvisited nodes
                int componentSize = dfs(dfs, i);
                // Update the maximum component size
                maxComponentSize = std::max(maxComponentSize, componentSize);
            }
        }

        return maxComponentSize;
}

