        std::vector<bool> visited(N, false);

        // Define a function to perform depth-first search
        auto dfs = [&](auto&& self, int node) -> int {
            if (visited[node]) return 0;
            visited[node] = true;
            int count = 1;
            for (int i = 0; i < N; ++i) {
