int maxDegree(std::vector<int> const& A, size_t N) {

        // Create a vector to store the degree of each node
        std::vector<int> degrees(N, 0);

        // Compute the degree of each node in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                if (A[i * N + j] == 1) {
