        for (int i = 0; i < N; ++i) {
            parent[i] = i;
        }

        // Find operation
        auto find = [&](int x) {
            if (parent[x]!= x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        };

        // Union operation
        auto union_sets = [&](int x, int y) {
