            int y_root = find(y);
            if (x_root!= y_root) {
                parent[x_root] = y_root;
            }
        };

        // Perform union operations for all edges in the graph
        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                if (A[i * N + j] == 1) {
                    union_sets(i, j);
                }
            }
        }

        // Count the number of connected components
        int count = 0;
        for (int i = 0; i < N; ++i) {
            if (parent[i] == i) {
                ++count;
            }
        }

        return count;
}

