        std::vector<bool> visited(N, false);
        int count = 0;

        // Define the HPX parallel for loop
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](int i) {
            if (!visited[i]) {
                count++;
                dfs(A, visited, i, N);
            }
        });

        return count;
}

