        // Initialize disjoint set data structure
        std::vector<int> parent(N);
        for (int i = 0; i < N; ++i)
            parent[i] = i;

        // Find operation
        auto find = [&](int x) {
            if (parent[x]!= x)
                parent[x] = find(parent[x]);
            return parent[x];
        };

        // Union operation
        auto merge = [&](int x, int y) {
            x = find(x);
            y = find(y);
            if (x!= y)
                parent[x] = y;
        };

        // Perform union operation for each edge in the graph
        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                if (A[i * N + j] == 1)
                    merge(i, j);
            }
        }

        // Count the number of connected components
        int count = 0;
        for (int i = 0; i < N; ++i) {
            if (parent[i] == i)
                ++count;
        }

        return count;
}

