        for (int i = 0; i < N; ++i) {
            parent[i] = i;
        }

        // Find the parent of a node
        auto find = [&](int x) {
            if (parent[x]!= x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        };

        // Union two nodes
        auto union_ = [&](int x, int y) {
            int px = find(x);
            int py = find(y);
            if (px!= py) {
                parent[px] = py;
            }
        };

        // Find the connected components
        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                if (A[i * N + j] == 1) {
                    union_(i, j);
                }
            }
        }

        // Count the number of connected components
        int count = 0;
        for (int i = 0; i < N; ++i) {
            if (parent[i] == i) {
                ++count;
            }
        }

        return count;
}

