int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {

        // Create a vector to store the distances from the source node to all other nodes
        std::vector<int> distances(N, INT_MAX);
        distances[source] = 0;

        // Create a priority queue to store the nodes to be processed
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
        pq.push({0, source});

        // Process the nodes in the priority queue
        while (!pq.empty()) {
            int u = pq.top().second;
            pq.pop();

            // Iterate over all neighbors of u
            for (int v = 0; v < N; ++v) {
                if (A[u * N + v] == 1) {
                    int alt = distances[u] + 1;
                    if (alt < distances[v]) {
                        distances[v] = alt;
                        pq.push({alt, v});
                    }
                }
            }
        }

        // Return the distance from the source to the destination
        return distances[dest];
}

