        std::vector<std::vector<int>> graph(N, std::vector<int>(N, 0));
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                if (A[i*N + j] == 1) {
                    graph[i][j] = 1;
                    graph[j][i] = 1;
