        // Create a distance vector and initialize it with infinity
        std::vector<int> distance(N, std::numeric_limits<int>::max());
        distance[source] = 0;

        // Create a visited vector and initialize it with false
        std::vector<bool> visited(N, false);

        // Create a queue for BFS
        std::queue<int> q;
        q.push(source);

        // Perform BFS
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            visited[u] = true;

