int shortestPathLength(std::vector<int> const& A, size_t N, int source, int dest) {

        // TODO: Implement the shortest path length calculation using HPX
        // You can use the HPX parallel_for algorithm to distribute the workload across multiple threads
        // You can use the HPX shared_future to get the result from the parallel computation
        // You can use the HPX latch to synchronize the threads

        // For example:

        hpx::lcos::local::latch l(N);
        std::vector<int> distances(N, std::numeric_limits<int>::max());
        distances[source] = 0;

        hpx::future<void> f = hpx::parallel::for_loop(
            hpx::parallel::execution::par, 0, N, [&](int i) {
                if (A[source * N + i] == 1 && i!= source) {
                    distances[i] = 1;
                }
                l.count_down();
            });

        l.wait();

        return distances[dest];
}

